companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page: page })
    return result.items
}
contacts = fold acc = first.items for page in remaining {
    return acc + page
}
domain_to_company = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

is_e164 = fun(phone) {
    return regex.test(phone, "^\\+1\\d{10}$")
}

to_e164 = fun(phone) {
    digits = regex.replace(phone, "[^0-9]", "")
    d = if text.starts_with(digits, "1") and text.length(digits) == 11 {
        return digits
    } else if text.length(digits) == 10 {
        return "1" + digits
    } else {
        return digits
    }
    return "+" + d
}

results = for contact in contacts {
    phone_needs = contact.phone != null and not regex.test(contact.phone, "^\\+1\\d{10}$")
    new_phone = to_e164(contact.phone) if phone_needs else null
    company_needs = (contact.company == null or contact.company == "") and contact.email != null
    domain = null
    filled_company = null
    if company_needs {
        parts = text.split(contact.email, "@")
        domain = parts[1] if list.length(parts) >= 2 else null
        filled_company = domain_to_company[domain] if domain != null and domain in domain_to_company else null
    }
    did_phone = phone_needs and new_phone != null
    did_company = filled_company != null
    skip if not did_phone and not did_company
    updated = update_contact({
        id: contact.id,
        phone: new_phone if did_phone else null,
        company: filled_company if did_company else null
    })
    return { phone: did_phone, company: did_company }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company else 0)
}
submitted = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submitted, total_contacts: list.length(contacts), updates: list.length(results) }

